import string

from hypothesis import strategies as st

NAME = "mxml_boundary_dense_fuzzer"
DESCRIPTION = (
    "Generates XML for a mxml v4.0.4 blackbox target. Threads element names "
    "through open/close tags so nesting is well-formed by construction, then "
    "places dense boundary sweeps (name length, attribute count, attribute "
    "value length, content length, nesting depth, charref value, entity name "
    "length) either standalone in clean documents or as one defect buried "
    "deep inside an otherwise valid nested document. Three buckets "
    "(well-formed, near-miss, byte-hostile) are combined with fixed category "
    "weights so the mixture stays in the required bands."
)

NAME_LENGTHS = sorted(set([1,2,3,4,5,8,15,16,17,31,32,33,63,64,65,99,100,101,
    127,128,129,199,200,201,254,255,256,257,300]))
ATTR_VALUE_LENGTHS = sorted(set([0,1,2,3,4,7,8,9,15,16,17,31,32,33,63,64,65,
    127,128,129,255,256,257,511,512,513,1023,1024,1025,2047,2048,2049,4095,4096,4097]))
ATTR_COUNTS = sorted(set([0,1,2,3,4,5,8,15,16,17,31,32,33,63,64,65,99,100,101,
    127,128,129,199,200,201,254,255,256,257]))
NESTING_DEPTHS = sorted(set([0,1,2,3,4,5,8,15,16,17,31,32,33,63,64,65,99,100,101,
    127,128,129,199,200,201,255,256,257,500,511,512,513,1000,2000,4096]))
CHARDATA_LENGTHS = sorted(set([0,1,2,3,4,7,8,9,15,16,17,31,32,33,63,64,65,
    127,128,129,255,256,257,511,512,513,1023,1024,1025]))
ENTITY_NAME_LENGTHS = sorted(set(list(range(1,21)) +
    [24,28,31,32,33,40,48,56,63,64,65,72,80,96,100,128,150,200,256]))
VALID_CHARREF_VALUES = [0x9,0x20,0x41,0x7E,0x7F,0x80,0xFF,0x100,0x7FF,0x800,
    0xD7FF,0xE000,0xFFFD,0xFFFF,0x10000,0x10FFFF]
DEC_OVERFLOW_DIGITS = [7,8,9,10,11,18,19,20,21,25,40]
HEX_OVERFLOW_DIGITS = [6,7,8,9,15,16,17,20,32]
MANY_ATTR_PAIRS = [(50,100),(50,400),(100,100),(100,200),(150,100),
    (200,100),(255,64),(1,4000),(1,4096)]

NAMED_ENTITIES = ["&amp;", "&lt;", "&gt;", "&quot;"]
UNSUPPORTED_ENTITY_NAMES = ["apos", "nbsp", "copy", "x", "Amp", "AMP", "LT", "quotation"]
BAD_CHARREF_KINDS = ["&#0;", "&#;", "&#x;", "&#xFFFFFFFFFFFF;",
    "&#99999999999999999999;", "&#4294967296;", "&#18446744073709551616;",
    "&#x110000;", "&#1114112;"]
ENCODING_NAMES = ["UTF-16", "ISO-8859-1", "EBCDIC-CP-US", "UTF-32", "Shift_JIS", "BOGUS-ENC"]

NAME_START_ASCII = list(string.ascii_letters) + ["_", ":"]
NAME_START_UNICODE_EXTRA = ["\u00e9", "\u0100", "\u017d", "\u03b1", "\u03a9",
    "\u1e9e", "\u2070", "\u2c00", "\u3001", "\uf900", "\ufdf0"]
NAME_START_POOL = NAME_START_ASCII + NAME_START_UNICODE_EXTRA
NAME_CHAR_EXTRA = list(string.digits) + ["-", ".", "\u00b7", "\u0300", "\u203f"]
NAME_CHAR_POOL = NAME_START_POOL + NAME_CHAR_EXTRA
SAFE_VALUE_CHARS = list(string.ascii_letters + string.digits + " -_.,:;!()")
SAFE_TEXT_CHARS = list(string.ascii_letters + string.digits + " .,-_!?()")


def rb(*byte_values):
    # Represent explicit raw bytes as a str via the surrogateescape convention,
    # so a harness that does text.encode('utf-8', 'surrogateescape') recovers
    # exactly these bytes, including ones that are not valid UTF-8 on their own.
    return "".join(chr(b) if b < 0x80 else chr(0xDC00 + b) for b in byte_values)


BOM_UTF8 = rb(0xEF, 0xBB, 0xBF)
BOM_UTF16_LE = rb(0xFF, 0xFE)
BOM_UTF16_BE = rb(0xFE, 0xFF)
OVERLONG_SLASH = rb(0xC0, 0xAF)
OVERLONG_NUL = rb(0xC0, 0x80)
TRUNCATED_3B = rb(0xE2, 0x82)
TRUNCATED_4B = rb(0xF0, 0x9F, 0x98)
TRUNCATED_LEAD_ONLY = rb(0xC3)
LONE_CONTINUATION = rb(0x80)
HOSTILE_UTF8_SNIPPETS = [TRUNCATED_3B, TRUNCATED_4B, TRUNCATED_LEAD_ONLY,
    LONE_CONTINUATION, OVERLONG_SLASH, OVERLONG_NUL]
CONTROL_CHARS = [chr(b) for b in list(range(1, 9)) + [11, 12] + list(range(14, 32))]
BAD_CHAR_POOL = ["\x00"] + CONTROL_CHARS

# ---- reusable building blocks ----


@st.composite
def st_name(draw, lengths=None):
    n = draw(st.sampled_from(lengths or NAME_LENGTHS))
    if n == 0:
        return ""
    first = draw(st.sampled_from(NAME_START_POOL))
    if n == 1:
        return first
    rest = draw(st.lists(st.sampled_from(NAME_CHAR_POOL), min_size=n - 1, max_size=n - 1))
    return first + "".join(rest)


@st.composite
def st_attr_value_plain(draw, lengths=None):
    n = draw(st.sampled_from(lengths or ATTR_VALUE_LENGTHS))
    chars = draw(st.lists(st.sampled_from(SAFE_VALUE_CHARS), min_size=n, max_size=n))
    return "".join(chars)


@st.composite
def st_chardata(draw, lengths=None):
    n = draw(st.sampled_from(lengths or CHARDATA_LENGTHS))
    chars = draw(st.lists(st.sampled_from(SAFE_TEXT_CHARS), min_size=n, max_size=n))
    return "".join(chars)


@st.composite
def st_attributes(draw, counts=None, dup=False):
    n = draw(st.sampled_from(counts or ATTR_COUNTS))
    names = []
    for _ in range(n):
        if dup and names and draw(st.sampled_from([True, False, False, False])):
            names.append(draw(st.sampled_from(names)))
        else:
            names.append(draw(st_name()))
    out = []
    for nm in names:
        q = draw(st.sampled_from(['"', "'"]))
        val = draw(st_attr_value_plain())
        out.append(f" {nm}={q}{val}{q}")
    return "".join(out)


@st.composite
def _wrap_chain(draw, leaf, max_depth=8):
    depth = draw(st.integers(min_value=0, max_value=max_depth))
    name = draw(st_name(lengths=[1, 2, 3]))
    inner = leaf
    for _ in range(depth):
        inner = f"<{name}>{inner}</{name}>"
    return inner


# ---- recursive element/content (name threaded through open+close) ----


@st.composite
def st_element(draw, depth_budget):
    name = draw(st_name())
    attrs = draw(st_attributes(counts=[0, 1, 2, 3], dup=True))
    if depth_budget <= 0 or draw(st.sampled_from([True, False, False])):
        return f"<{name}{attrs}/>"
    content = draw(st_content(depth_budget - 1))
    return f"<{name}{attrs}>{content}</{name}>"


@st.composite
def st_content(draw, depth_budget):
    # At most one recursive child per level: worst case size/time is linear
    # in depth_budget, never exponential, however large depth_budget gets.
    parts = [draw(st_chardata(lengths=[0, 1, 2, 5, 20]))]
    extra = draw(st.integers(min_value=0, max_value=3))
    kinds = ["entity", "charref_dec", "charref_hex", "cdata", "comment", "pi", "text"]
    for _ in range(extra):
        kind = draw(st.sampled_from(kinds))
        if kind == "entity":
            parts.append(draw(st.sampled_from(NAMED_ENTITIES)))
        elif kind == "charref_dec":
            parts.append(f"&#{draw(st.sampled_from(VALID_CHARREF_VALUES))};")
        elif kind == "charref_hex":
            parts.append(f"&#x{draw(st.sampled_from(VALID_CHARREF_VALUES)):x};")
        elif kind == "cdata":
            parts.append(f"<![CDATA[{draw(st_chardata(lengths=[0, 5, 20]))}]]>")
        elif kind == "comment":
            parts.append(f"<!--{draw(st_chardata(lengths=[0, 5, 20]))}-->")
        elif kind == "pi":
            parts.append(f"<?{draw(st_name(lengths=[1, 3, 8]))}?>")
        else:
            parts.append(draw(st_chardata(lengths=[0, 1, 5, 20])))
    if depth_budget > 0 and draw(st.sampled_from([True, False, False])):
        parts.append(draw(st_element(depth_budget - 1)))
    return "".join(parts)


# ---- well_formed generators ----


@st.composite
def wf_prolog_and_element(draw):
    kind = draw(st.sampled_from(["full", "no_space", "none"]))
    depth = draw(st.sampled_from([0, 1, 2, 3, 5]))
    body = draw(st_element(depth))
    if kind == "full":
        return '<?xml version="1.0" encoding="UTF-8"?>' + body
    if kind == "no_space":
        return "<?xml?>" + body
    return body


@st.composite
def wf_paired_with_content(draw):
    depth = draw(st.sampled_from([0, 1, 2, 3, 4, 5, 6, 8, 12, 16]))
    return draw(st_element(depth))


@st.composite
def wf_selfclose_attrs(draw):
    name = draw(st_name())
    kind = draw(st.sampled_from(["count", "value", "dup"]))
    if kind == "count":
        attrs = draw(st_attributes(counts=ATTR_COUNTS))
    elif kind == "value":
        an = draw(st_name(lengths=[1, 3, 8]))
        q = draw(st.sampled_from(['"', "'"]))
        val = draw(st_attr_value_plain(lengths=ATTR_VALUE_LENGTHS))
        attrs = f" {an}={q}{val}{q}"
    else:
        attrs = draw(st_attributes(counts=[2, 3, 5, 8], dup=True))
    return f"<{name}{attrs}/>"


@st.composite
def wf_name_length_sweep(draw):
    name = draw(st_name(lengths=NAME_LENGTHS))
    if draw(st.booleans()):
        return f"<{name}/>"
    content = draw(st_chardata(lengths=[0, 5, 20]))
    return f"<{name}>{content}</{name}>"


@st.composite
def wf_deep_chain(draw):
    depth = draw(st.sampled_from(NESTING_DEPTHS))
    name = draw(st.sampled_from(list(string.ascii_lowercase)))
    if depth == 0:
        return f"<{name}/>"
    leaf = draw(st_chardata(lengths=[0, 1, 5, 20]))
    return f"<{name}>" * depth + leaf + f"</{name}>" * depth


@st.composite
def wf_combo_longname_deepnest(draw):
    depth = draw(st.sampled_from([2, 3, 5, 8, 13, 21, 34, 55]))
    name = draw(st_name(lengths=[64, 100, 128, 200, 255, 256, 257, 300]))
    inner = f"<{name}/>"
    for _ in range(depth):
        inner = f"<{name}>{inner}</{name}>"
    return inner


@st.composite
def wf_combo_many_attrs_longvals(draw):
    count, vlen = draw(st.sampled_from(MANY_ATTR_PAIRS))
    name = draw(st_name())
    parts = []
    for _ in range(count):
        an = draw(st_name(lengths=[1, 2, 3, 5]))
        val = "".join(draw(st.lists(st.sampled_from(SAFE_VALUE_CHARS), min_size=vlen, max_size=vlen)))
        parts.append(f' {an}="{val}"')
    return f"<{name}{''.join(parts)}/>"


@st.composite
def wf_content_length_sweep(draw):
    name = draw(st_name())
    content = draw(st_chardata(lengths=CHARDATA_LENGTHS))
    return f"<{name}>{content}</{name}>"


@st.composite
def wf_unquoted_attr(draw):
    name = draw(st_name())
    an = draw(st_name(lengths=[1, 2, 3, 5]))
    val = draw(st.sampled_from(["1", "0", "true", "abc123", "x", "99"]))
    return f"<{name} {an}={val}/>"


@st.composite
def wf_doctype(draw):
    root = draw(st_name())
    return f"<!DOCTYPE {root} [<!ELEMENT {root} EMPTY>]><{root}/>"


@st.composite
def wf_empty_name(draw):
    ws = draw(st.sampled_from([" ", "  ", "\t"]))
    return f"<{ws}/>"


@st.composite
def wf_nonascii_name(draw):
    start = draw(st.sampled_from(NAME_START_UNICODE_EXTRA))
    rest_len = draw(st.sampled_from([0, 1, 2, 5, 10]))
    rest = "".join(draw(st.lists(st.sampled_from(NAME_CHAR_POOL), min_size=rest_len, max_size=rest_len)))
    return f"<{start}{rest}/>"


@st.composite
def wf_rootless(draw):
    kind = draw(st.sampled_from(["comment", "pi", "ws"]))
    if kind == "comment":
        body = draw(st_chardata(lengths=[0, 5, 20]))
        return f"<!--{body}-->"
    if kind == "pi":
        name = draw(st_name(lengths=[1, 3, 8]))
        return f"<?{name}?>"
    return draw(st.sampled_from([" ", "\n", "\t\n ", "\r\n"]))


WELL_FORMED = [wf_prolog_and_element, wf_paired_with_content, wf_selfclose_attrs,
    wf_name_length_sweep, wf_deep_chain, wf_combo_longname_deepnest,
    wf_combo_many_attrs_longvals, wf_content_length_sweep, wf_unquoted_attr,
    wf_doctype, wf_empty_name, wf_nonascii_name, wf_rootless]

# ---- near_miss generators: XML-shaped, clean bytes, structurally wrong ----


@st.composite
def nm_mismatched_tags(draw):
    depth = draw(st.sampled_from([1, 2, 3, 5, 8]))
    name = draw(st_name())
    wrong = draw(st_name())
    return f"<{name}>" * depth + f"</{name}>" * (depth - 1) + f"</{wrong}>"


@st.composite
def nm_unclosed_element(draw):
    depth = draw(st.sampled_from([1, 2, 3, 5, 8, 13]))
    name = draw(st_name())
    return f"<{name}>" * depth


@st.composite
def nm_extra_close_tag(draw):
    name = draw(st_name())
    return f"<{name}/></{name}>"


@st.composite
def nm_unsupported_entity(draw):
    depth = draw(st.sampled_from([0, 1, 3, 5]))
    name = draw(st_name())
    ent = draw(st.sampled_from(UNSUPPORTED_ENTITY_NAMES))
    inner = f"<{name}>&{ent};</{name}>"
    for _ in range(depth):
        inner = f"<{name}>{inner}</{name}>"
    return inner


@st.composite
def nm_bad_charref(draw):
    name = draw(st_name())
    ref = draw(st.sampled_from(BAD_CHARREF_KINDS))
    return f"<{name}>{ref}</{name}>"


@st.composite
def nm_charref_overflow(draw):
    name = draw(st_name())
    if draw(st.booleans()):
        n = draw(st.sampled_from(DEC_OVERFLOW_DIGITS))
        ref = f"&#{'9' * n};"
    else:
        n = draw(st.sampled_from(HEX_OVERFLOW_DIGITS))
        ref = f"&#x{'F' * n};"
    return f"<{name}>{ref}</{name}>"


@st.composite
def nm_unterminated(draw):
    kind = draw(st.sampled_from(["comment", "cdata"]))
    name = draw(st_name())
    body = draw(st_chardata(lengths=[0, 5, 20]))
    opener = "<!--" if kind == "comment" else "<![CDATA["
    return draw(_wrap_chain(f"<{name}>{opener}{body}", max_depth=6))


@st.composite
def nm_unterminated_attr_string(draw):
    name = draw(st_name())
    an = draw(st_name())
    val = draw(st_attr_value_plain(lengths=[1, 5, 20]))
    q = draw(st.sampled_from(['"', "'"]))
    return f"<{name} {an}={q}{val}/>"


@st.composite
def nm_multiple_roots(draw):
    a = draw(st_name())
    b = draw(st_name())
    return f"<{a}/><{b}/>"


@st.composite
def nm_bad_attribute_syntax(draw):
    name = draw(st_name())
    an = draw(st_name())
    kind = draw(st.sampled_from(["no_eq", "no_val", "eq_no_val"]))
    if kind == "no_eq":
        return f"<{name} {an}/>"
    if kind == "no_val":
        return f"<{name} {an}=/>"
    return f"<{name} {an}= />"


@st.composite
def nm_entity_name_length_sweep(draw):
    length = draw(st.sampled_from(ENTITY_NAME_LENGTHS))
    letters = draw(st.lists(st.sampled_from(string.ascii_lowercase), min_size=length, max_size=length))
    name = draw(st_name())
    return f"<{name}>&{''.join(letters)};</{name}>"


NEAR_MISS = [nm_mismatched_tags, nm_unclosed_element, nm_extra_close_tag,
    nm_unsupported_entity, nm_bad_charref, nm_charref_overflow, nm_unterminated,
    nm_unterminated_attr_string, nm_multiple_roots, nm_bad_attribute_syntax,
    nm_entity_name_length_sweep]

# ---- byte_hostile generators: hostile bytes buried in a valid-shaped chain ----


@st.composite
def bh_utf8_bom(draw):
    return BOM_UTF8 + draw(wf_paired_with_content())


@st.composite
def bh_utf16_bom_odd(draw):
    bom = draw(st.sampled_from([BOM_UTF16_LE, BOM_UTF16_BE]))
    n = draw(st.sampled_from([1, 3, 5, 7]))
    junk = "".join(draw(st.lists(st.sampled_from(string.ascii_letters), min_size=n, max_size=n)))
    return bom + junk + draw(wf_paired_with_content())


@st.composite
def bh_invalid_utf8(draw):
    name = draw(st_name())
    snippet = draw(st.sampled_from(HOSTILE_UTF8_SNIPPETS))
    if draw(st.sampled_from(["attr", "text"])) == "attr":
        an = draw(st_name(lengths=[1, 3, 8]))
        val = draw(st_attr_value_plain(lengths=[0, 5, 20]))
        leaf = f'<{name} {an}="{val}{snippet}{val}"/>'
    else:
        txt = draw(st_chardata(lengths=[0, 5, 20]))
        leaf = f"<{name}>{txt}{snippet}{txt}</{name}>"
    return draw(_wrap_chain(leaf))


@st.composite
def bh_bad_char(draw):
    name = draw(st_name())
    c = draw(st.sampled_from(BAD_CHAR_POOL))
    if draw(st.sampled_from(["attr", "text"])) == "attr":
        an = draw(st_name(lengths=[1, 3]))
        val = draw(st_attr_value_plain(lengths=[0, 5, 20]))
        leaf = f'<{name} {an}="{val}{c}{val}"/>'
    else:
        txt = draw(st_chardata(lengths=[0, 5, 20]))
        leaf = f"<{name}>{txt}{c}{txt}</{name}>"
    return draw(_wrap_chain(leaf))


@st.composite
def bh_contradictory_encoding(draw):
    enc = draw(st.sampled_from(ENCODING_NAMES))
    name = draw(st_name())
    snippet = draw(st.sampled_from(HOSTILE_UTF8_SNIPPETS + [""]))
    body = draw(_wrap_chain(f"<{name}>{snippet}text</{name}>", max_depth=5))
    return f'<?xml version="1.0" encoding="{enc}"?>' + body


BYTE_HOSTILE = [bh_utf8_bom, bh_utf16_bom_odd, bh_invalid_utf8, bh_bad_char,
    bh_contradictory_encoding]


def documents():
    # Category-level weighting (4:3:3 -> ~40%/30%/30% nominal) keeps the
    # mixture safely inside well_formed>=35%, near_miss>=15%, byte_hostile
    # in [15%,45%], regardless of how many variants sit inside each bucket.
    wf_cat = st.one_of([g() for g in WELL_FORMED])
    nm_cat = st.one_of([g() for g in NEAR_MISS])
    bh_cat = st.one_of([g() for g in BYTE_HOSTILE])
    return st.one_of([wf_cat, wf_cat, wf_cat, wf_cat, nm_cat, nm_cat, nm_cat,
        bh_cat, bh_cat, bh_cat])
